{
  "name": "opencode-user-message-jumper",
  "version": "0.1.1",
  "description": "OpenCode TUI plugin that adds a user-message index to the session sidebar.",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/asukaneko/opencode-user-message-jumper.git"
  },
  "bugs": {
    "url": "https://github.com/asukaneko/opencode-user-message-jumper/issues"
  },
  "homepage": "https://github.com/asukaneko/opencode-user-message-jumper#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui"
  ],
  "oc-plugin": [
    "tui"
  ],
  "exports": {
    ".": {
      "import": "./dist/tui.js",
      "config": {
        "limit": "12",
        "openDetailOnSidebarClick": "true"
      }
    },
    "./tui": {
      "import": "./dist/tui.js",
      "config": {
        "limit": "12",
        "openDetailOnSidebarClick": "true"
      }
    }
  },
  "files": [
    "dist",
    "src",
    "README.md",
    "package.json"
  ],
  "scripts": {
    "build:dist": "bun ./scripts/build.mjs",
    "prepublishOnly": "bun run build:dist",
    "smoke": "bun ./scripts/smoke.mjs",
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.17.11",
    "@opencode-ai/sdk": "^1.17.11",
    "@opentui/core": "^0.4.2",
    "@opentui/solid": "^0.4.2",
    "solid-js": "1.9.12"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opencode-ai/sdk": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.17.11",
    "@opencode-ai/sdk": "^1.17.11",
    "@opentui/core": "^0.4.2",
    "@opentui/solid": "^0.4.2",
    "solid-js": "1.9.12",
    "@types/bun": "latest",
    "typescript": "^5.9.3"
  },
  "engines": {
    "opencode": ">=1.17.11"
  }
}
